package dev.ipf.whitenoise.android.media.pdf

import java.util.Base64
import java.util.zip.DataFormatException
import java.util.zip.Inflater

// Test-only PDF helpers for #3377. They read bytes independently of the production parser, so a scrubber bug cannot
// hide behind a shared reader.

/** The committed fixtures, generated by scripts/generate_pdf_metadata_fixtures.py. */
internal val CLEANABLE_PDF_FIXTURES =
    listOf("ghostscript", "object-streams", "flate-xmp", "incremental", "form-photo", "pdfa")

/** Private values the fixtures carry somewhere: document information, XMP, an old revision or a photo. */
internal val PDF_PRIVATE_VALUES =
    listOf(
        "WNPrivateAuthor",
        "WNPrivateTitle",
        "WNPrivateSubject",
        "WNPrivateKeywords",
        "WNPrivateCreator",
        "WNPrivateCompany",
        "WNPrivateSecondAuthor",
        "WNPrivateEditor",
        "WNPrivateIndirect",
        "WNPrivateCamera",
        "WNPrivateModel",
        "WNPrivateComment",
        "Ghostscript",
        "2024-05-06",
    )

/** Decodes one committed fixture from the JVM test resources. */
internal fun pdfFixture(name: String): ByteArray {
    val stream = checkNotNull(PdfFixtureMarker::class.java.getResourceAsStream("/pdf-metadata/$name.pdf.b64")) { name }
    return Base64.getMimeDecoder().decode(stream.use { it.readBytes() })
}

private object PdfFixtureMarker

/** The raw bytes followed by the inflated content of every stream that inflates, as one searchable text. */
internal fun pdfSearchableText(bytes: ByteArray): String {
    val text = StringBuilder(String(bytes, Charsets.ISO_8859_1))
    val raw = text.toString()
    Regex("stream\r?\n").findAll(raw).forEach { match ->
        inflateOrNull(bytes, match.range.last + 1)?.let { text.append('\n').append(String(it, Charsets.ISO_8859_1)) }
    }
    return text.toString()
}

private fun inflateOrNull(
    bytes: ByteArray,
    start: Int,
): ByteArray? {
    val inflater = Inflater()
    return try {
        inflater.setInput(bytes, start, bytes.size - start)
        val output = ByteArray(1 shl 20)
        val count = inflater.inflate(output)
        if (count == 0) null else output.copyOf(count)
    } catch (_: DataFormatException) {
        null
    } finally {
        inflater.end()
    }
}

/** Private values from [PDF_PRIVATE_VALUES] still readable anywhere in [bytes]. */
internal fun leakedPdfValues(bytes: ByteArray): List<String> {
    val text = pdfSearchableText(bytes)
    return PDF_PRIVATE_VALUES.filter { it in text }
}
